// These tests replay vectors produced by the PYTHON backend (golden.json, generated by
// scripts/make_golden_fixtures.py). If one fails, the browser and the backend disagree
// about a number - which would mean a chart shows something the rules do not see.
import { describe, expect, it } from 'vitest'
import golden from './golden.json'
import { computeIndicator } from './indicators'
import { anchorIndex, indexToTime, lineSeries } from './lines'
import { bucketEnd, bucketStart, inSession } from './timeframes'
import type { IndicatorName, Timeframe, Drawing } from '../api/types'

const near = (actual: number, expected: number | null, tol = 1e-7) => {
  if (expected === null) expect(Number.isNaN(actual)).toBe(true)
  else expect(Math.abs(actual - expected)).toBeLessThanOrEqual(tol * Math.max(1, Math.abs(expected)))
}

describe('indicators match the Python implementation', () => {
  const { open: _o, ...ohlc } = golden.series
  void _o
  for (const c of golden.indicators) {
    it(`${c.name} ${JSON.stringify(c.params)}`, () => {
      const out = computeIndicator(c.name as IndicatorName, c.params as unknown as Record<string, number>, ohlc)
      expect(Object.keys(out).sort()).toEqual(Object.keys(c.outputs).sort())
      for (const [key, expected] of Object.entries(c.outputs) as [string, (number | null)[]][]) {
        expect(out[key]).toHaveLength(expected.length)
        expected.forEach((e, i) => near(out[key][i], e))
      }
    })
  }
})

describe('timeframe buckets match the Python implementation', () => {
  for (const row of golden.timeframes) {
    const when = new Date(row.ts * 1000).toISOString()
    it(`${row.symbol} at ${when}`, () => {
      expect(inSession(row.ts, row.exchange)).toBe(row.in_session)
      for (const [tf, b] of Object.entries(row.buckets) as [Timeframe, { start: number; end: number }][]) {
        const start = bucketStart(row.ts, tf, row.exchange)
        expect({ tf, start, end: bucketEnd(start, tf, row.exchange) }).toEqual({ tf, start: b.start, end: b.end })
      }
    })
  }
})

describe('trend lines match the Python implementation (bar-index space)', () => {
  const c = golden.lines[0]
  it('maps times onto the bar axis identically', () => {
    for (const a of c.anchors) near(anchorIndex(c.times, a.t, 3600), a.index, 1e-9)
  })
  it('indexToTime inverts anchorIndex', () => {
    for (const a of c.anchors) near(indexToTime(c.times, anchorIndex(c.times, a.t, 3600), 3600), a.t, 1e-9)
  })
  for (const d of c.drawings as Drawing[]) {
    it(`${d.kind} ${d.id} has the same price on every bar`, () => {
      const got = lineSeries(d, c.times, 3600)
      const expected = (c.series as Record<string, (number | null)[]>)[d.id]
      got.forEach((v, i) => near(v ?? NaN, expected[i], 1e-9))
    })
  }
})
